<?php require_once __DIR__.'/../../includes/functions.php';$u=require_auth();$q=trim($_GET['q']??'');$type=trim($_GET['type']??'all');$sql="SELECT * FROM files WHERE user_id=? AND is_deleted=0 AND file_name LIKE ?";$params=[$u['id'],'%'.$q.'%'];if($type!=='all'){ $map=['documents'=>'Documents','images'=>'Images','videos'=>'Videos','audio'=>'Audio','archives'=>'Archives']; if(isset($map[$type])){$sql.=' AND ';$needle=['Documents'=>'application','Images'=>'image/','Videos'=>'video/','Audio'=>'audio/','Archives'=>'zip'][ $map[$type] ];$sql.='mime_type LIKE ?';$params[]='%'.$needle.'%';}}$sql.=' ORDER BY updated_at DESC LIMIT 100';$st=db()->prepare($sql);$st->execute($params);$rows=$st->fetchAll();json_response(['results'=>$rows]);